    Source: packages/compose-gen/specs/organisms/pricing-card.json
    A plan as a card: name, tagline, price per month, the features, a call to action and an optional slot for more actions. Text comes in through `labels`; the plan is data.
    Props (p): plan, labels, current, emphasis, density, billing, footer (slot: plan). *}
{var $v_plan = ($p['plan'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_current = ($p['current'] ?? null)}
{var $v_emphasis = ($p['emphasis'] ?? 'auto')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_billing = ($p['billing'] ?? 'monthly')}
{var $v_stand = og_and([og_get($v_plan, ['highlighted']), og_eq($v_emphasis, 'auto')])}
{var $v_yearlyOn = og_and([og_eq($v_billing, 'annual'), og_gt(og_get($v_plan, ['yearly']), 0)])}
{var $v_amount = (og_t($v_yearlyOn) ? og_get($v_plan, ['yearly']) : og_get($v_plan, ['price']))}
{capture $c_16}
  {capture $c_5}
    {capture $c_2}
      {if og_t($v_stand)}
        {capture $c_1}
          {=og_text(og_get($v_labels, ['popular']))}
        {/capture}
        {=og_include('compose/Badge.latte', ['variant' => 'default', 'size' => 'default', 'children' => (string) $c_1])|noescape}
      {/if}
    {/capture}
    {=og_include('compose/Box.latte', ['class' => 'flex min-h-6 items-center', 'attrs' => og_attrs(['data-slot', 'badge-slot']), 'children' => (string) $c_2])|noescape}
    {capture $c_3}
      {=og_text(og_get($v_plan, ['name']))}
    {/capture}
    {=og_include('compose/CardTitle.latte', ['as' => 3, 'children' => (string) $c_3])|noescape}
    {capture $c_4}
      {=og_text(og_get($v_plan, ['tagline']))}
    {/capture}
    {=og_include('compose/CardDescription.latte', ['children' => (string) $c_4])|noescape}
  {/capture}
  {=og_include('compose/CardHeader.latte', ['class' => 'flex flex-col gap-2', 'children' => (string) $c_5])|noescape}
  {capture $c_13}
    {capture $c_8}
      {capture $c_6}
        {if og_t(og_eq($v_amount, 0))}
          {=og_text(og_get($v_labels, ['free']))}
        {else}
          {=og_text(og_money($v_amount, og_get($v_plan, ['currency'])))}
        {/if}
      {/capture}
      {=og_include('compose/Title.latte', ['as' => 2, 'size' => '4xl', 'weight' => 'bold', 'children' => (string) $c_6])|noescape}
      {if og_t(og_gt($v_amount, 0))}
        {capture $c_7}
          {=og_text((og_t($v_yearlyOn) ? og_get($v_labels, ['perYear']) : og_get($v_labels, ['perMonth'])))}
        {/capture}
        {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_7])|noescape}
      {/if}
    {/capture}
    {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'baseline', 'children' => (string) $c_8])|noescape}
    {capture $c_9}
      {=og_text(og_tpl(og_get($v_labels, ['seats']), [og_get($v_plan, ['seats'])]))}
    {/capture}
    {=og_include('compose/Text.latte', ['size' => 'sm', 'weight' => 'medium', 'children' => (string) $c_9])|noescape}
    {capture $c_10}
      {=og_text(og_tpl(og_get($v_labels, ['storage']), [og_get($v_plan, ['storage'])]))}
    {/capture}
    {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_10])|noescape}
    {capture $c_12}
      {foreach og_l(og_get($v_plan, ['features'])) as $v_feature}
        {capture $c_11}
          {=og_text($v_feature)}
        {/capture}
        {=og_include('compose/ListItem.latte', ['class' => 'flex gap-2', 'attrs' => og_attrs(['data-slot', 'features-row']), 'children' => (string) $c_11])|noescape}
      {/foreach}
    {/capture}
    {=og_include('compose/List.latte', ['tag' => 'ul', 'class' => 'flex flex-col gap-2 text-sm', 'children' => (string) $c_12])|noescape}
  {/capture}
  {=og_include('compose/CardContent.latte', ['class' => og_s(og_cnv(['flex flex-1 flex-col', (og_t(og_eq($v_density, 'compact')) ? 'gap-2' : 'gap-4')])), 'children' => (string) $c_13])|noescape}
  {capture $c_15}
    {capture $c_14}
      {=og_text(og_get($v_labels, ['cta']))}
    {/capture}
    {=og_include('compose/Button.latte', ['variant' => og_s((og_t($v_stand) ? 'default' : 'outline')), 'size' => 'default', 'children' => (string) $c_14])|noescape}
    {if (($p['footer'] ?? null) !== null)}
      {=og_include($p['footer']['t'], array_merge($p['footer']['v'], ['a0' => $v_plan]))|noescape}
    {/if}
  {/capture}
  {=og_include('compose/CardFooter.latte', ['class' => 'flex flex-wrap items-center gap-2', 'children' => (string) $c_15])|noescape}
{/capture}
{=og_include('compose/Block.latte', ['tag' => 'article', 'class' => og_s(og_cnv(['flex flex-col gap-8 bg-card p-6 text-card-foreground inset-ring inset-ring-border rounded', 'flex h-full flex-col'])), 'attrs' => og_attrs(['data-slot', 'card', 'data-highlighted', (og_t($v_stand) ? 'true' : 'false'), 'data-current', (og_t($v_current) ? 'true' : 'false')]), 'children' => (string) $c_16])|noescape}
